B={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1),(3,1),(3,2)}
def norm(S):
 r0=min(x for x,y in S); c0=min(y for x,y in S)
 return frozenset((x-r0,y-c0) for x,y in S)
def transforms(S):
 out=[]
 for refl in [False,True]:
  for rot in range(4):
   t=set()
   for x,y in S:
    if refl: y=-y
    for _ in range(rot): x,y=y,-x
    t.add((x,y))
   out.append(norm(t))
 return out
[(a==b) for a in transforms(A) for b in [norm(B)]]
